    if(state.path==='relief')out.innerHTML=common+'<div class="grid3 divider"><div><div class="label">Rate test</div><div class="display-value warn-text" data-value="UST10Y">5.10%</div><div class="small muted">Needs a close below '+state.rule.confirm.toFixed(2)+'%.</div></div><div><div class="label">Credit test</div><div class="display-value warn-text" data-value="peerMean">+11 bp</div><div class="small muted">Matched peer mean needs +'+state.rule.peerMean+' bp.</div></div><div><div class="label">Funding test</div><div class="display-value good-text">Orderly</div><div class="small muted">Must remain current and orderly.</div></div></div><div class="row spread divider"><div><strong>All three must hold within five eligible closes.</strong><div class="small bad-text">A close above '+state.rule.invalidate.toFixed(2)+'% or funding stress ends this test.</div><div class="small muted" style="margin-top:6px">A matched test does not establish the cause or guarantee continuation.</div></div>'+B('Review conditions','conditions',true)+'</div>';
    else out.innerHTML=common+'<div class="grid2 divider"><div class="stack"><div class="label">If</div><strong>'+p.if+'</strong><div class="label">Then watch</div><span>'+p.outcome+'</span></div><div class="stack"><div class="label">Next discriminating check</div><strong>'+p.next+'</strong><span class="small muted">'+(state.path==='stress'?'Funding is currently orderly; this remains counterevidence.':'Auction-specific evidence is not loaded in this fixture.')+'</span></div></div><div class="case-note warn"><span>The rate-relief rule needs review for this outlook.</span>'+B('Review attached rule','conditions')+'</div>';
