      $('#dialog-content').innerHTML='<div class="stack"><p>Unapplied tool edits: '+Object.keys(state.modalDirty).filter(k=>state.modalDirty[k]).map(k=>esc(toolTitles[k])).join(', ')+'.</p><p class="small muted">Your applied case additions and main-page assumptions are separate.</p><div class="actions">'+B('Keep editing','keep-editing',true)+B('Discard unapplied tool edits','discard-edits')+'</div></div>';bindActions($('#dialog-content'));$('#dialog-close').focus();return;
