  function ruleView(args={}) { const displayed=L.finite(args.confirm)&&L.finite(args.invalidate)?args:state.rule; return '<div class="stack"><p>Set a lower observation level and a higher invalidation level for the same Treasury series.</p><div class="grid2">'+field('Close below (%)','rule-confirm',displayed.confirm,'type="number" step="0.01" min="0.01"')+field('Invalidate above (%)','rule-invalidate',displayed.invalidate,'type="number" step="0.01" min="0.01"')+'</div><div id="rule-error" class="field-error" role="status"></div><details><summary>Optional retest rule</summary><p>The authored example is: break below 5.08%; retest 5.06–5.08% within three eligible sessions; the following close is lower and still below 5.08%. A move above 5.22% ends that test. This optional sequence is a separate rule, not an extra confidence vote.</p></details><div class="actions">'+B('Back to structure','structure')+B('Apply price conditions','commit-rule',true)+'</div></div>'; }
  function refreshRule() { if(!$('#rule-confirm'))return;const c=number('rule-confirm'),i=number('rule-invalidate'),valid=L.finite(c)&&L.finite(i)&&c>0&&c<i;$('#rule-error').textContent=valid?'':'Enter two valid levels; the lower trigger must be below invalidation.';$('#dialog-content [data-action=commit-rule]').disabled=!valid; }
  function shapeView() { return '<div class="stack"><div class="row spread"><h3 class="section-title">A curve twist changes the result</h3>'+chip('First order','blue')+'</div><p class="muted">Same synthetic USD Treasury curve, cutoff and four-node sensitivity vector.</p><div class="grid2">'+['2Y','5Y','10Y','30Y'].map((t,i)=>field(t+' shock (bp)','shape-'+i,state.shape?.shocks?.[i]??[-15,-10,5,12][i],'type="number" step="1"')).join('')+'</div><div id="shape-output" class="status-line" role="status"></div><details><summary>Inspect key-rate contributions</summary><div id="shape-table"></div><p class="small muted">ΔP/P ≈ −Σ KRDᵢ × Δyᵢ. This first-order result excludes convexity, carry, spread and FX. The scalar convexity is not reused for a curve twist.</p></details><div class="actions dialog-sticky-actions">'+B('Cancel','close')+B('Apply curve shape','apply-shape',true)+'</div></div>'; }
  function refreshShape() { if(!$('#shape-output'))return;const v=[0,1,2,3].map(i=>number('shape-'+i)),r=L.keyRate([.2,1.1,5.2,1.3],v);$('#shape-output').innerHTML=r?'<div class="label">Treasury price sensitivity</div><div class="display-value '+(r.total>=0?'good-text':'bad-text')+'" data-testid="shape-result">'+fmt(r.total)+'%</div>':'<strong>Calculation unavailable</strong><div>Complete all four compatible node shocks. Missing is not zero.</div>';$('#shape-table').innerHTML=r?'<table class="measure-list"><thead><tr><th>Tenor</th><th>KRD</th><th>Shock</th><th>Contribution</th></tr></thead><tbody>'+r.contributions.map((x,i)=>'<tr><td>'+['2Y','5Y','10Y','30Y'][i]+'</td><td>'+[.2,1.1,5.2,1.3][i]+'</td><td>'+v[i]+' bp</td><td>'+fmt(x,3)+'%</td></tr>').join('')+'</tbody></table>':'';$('#dialog-content [data-action=apply-shape]').disabled=!r; }
  function cashView() {return '<div class="stack"><div class="row spread"><div><h3 class="section-title">Cash is needed before the cutoff</h3><div class="small muted">Synthetic Parent A · USD millions · 16 Oct 2026 to 15 Jan 2027</div></div>'+chip('Manual scenario','warn')+'</div><div class="grid2">'+select('Eligible $900m draw','cash-draw',[['none','No assumed draw'],['before','Before payment cutoff'],['late','After payment cutoff']],state.cash.draw)+select('$200m operating receipt','cash-receipt',[['on_time','Assume receipt on time'],['delayed','Delay beyond the window']],state.cash.delayReceipt?'delayed':'on_time')+'</div><div id="cash-output" role="status"></div><details><summary>All cash events and assumptions</summary><div id="cash-events"></div><p class="small muted">Opening usable cash is $3,000m less $900m restricted. A $300m buffer is tested separately. Eligible draw = min(1,500 − 400 drawn − 200 LC capacity, 1,000 borrowing base) = $900m. Same borrower, permitted use, conditions, and settlement eligibility are assumed; in-window draw fees and interest payments are assumed zero.</p><p class="small muted">A projected shortfall is a financing need, not proof of an actual bank overdraft or legal default. Later cash assumes overdue obligations can subsequently be paid.</p></details><div class="actions dialog-sticky-actions">'+B('Reported CoreWeave schedule','financing')+B('Add cash scenario to current draft','apply-cash',true)+'</div><div class="small muted">The current research borrower is '+esc(state.context.borrower)+'. A different borrower must use a separate case.</div></div>';}
  function refreshCash() { if(!$('#cash-draw'))return;const r=L.cashProjection({draw:$('#cash-draw').value,delayReceipt:$('#cash-receipt').value==='delayed'});$('#cash-output').innerHTML='<div class="grid3"><div class="soft-panel"><div class="label">Payment-time financing need</div><div class="display-value '+(r.paymentGap?'bad-text':'good-text')+'" data-testid="cash-gap">$'+r.paymentGap+'m</div></div><div class="soft-panel"><div class="label">Cash after scheduled events</div><div class="display-value" data-testid="cash-ending">$'+r.ending+'m</div></div><div class="soft-panel"><div class="label">Buffer funding need at cutoff</div><div class="display-value">$'+r.bufferGap+'m</div></div></div>'+lineChart(r.rows.map(x=>x.balance),{lo:-400,hi:2300,label:'Projected usable cash in millions',endLabel:'End of scenario',thresholds:[{value:300,label:'$300m buffer',color:'var(--mx-light-ink-warn)'},{value:0,label:'Payment coverage',color:'var(--mx-light-ink-down)'}]})+(r.paymentGap&&$('#cash-draw').value==='late'?'<div class="status-line" data-state="invalidated"><strong>Later cash does not cure timely coverage.</strong><div>The $'+r.paymentGap+'m shortfall occurs at 09:00; the draw arrives at 16:00 in the scenario clock.</div></div>':'');$('#cash-events').innerHTML='<table class="measure-list"><thead><tr><th>Scenario time</th><th>Event</th><th>Change</th><th>Balance</th></tr></thead><tbody>'+r.rows.map(x=>'<tr><td>'+x.time.slice(0,16).replace('T',' ')+'</td><td>'+x.label+'</td><td>'+fmt(x.amount,0)+'</td><td>'+x.balance+'</td></tr>').join('')+'</tbody></table>'; }
