      '<div class="case-note"><strong>Activation unavailable</strong><span>The existing alert service does not yet admit this complete yield, credit and funding rule.</span></div><div class="actions dialog-sticky-actions">'+B('Edit price levels','rule')+B('Keep working','close',true)+'<button type="button" class="button" disabled>Activation unavailable</button></div></div>';
