    const op={operationId:'demo-question-op-'+(++state.operationCounter),expectedRevision:state.demoRecord?.revision||0,payload:{subject:'CoreWeave',question,nextCheck,horizon:state.context.horizon},scope:'question_and_next_check_only'};
    if(state.saveMode==='unknown'){clearToolDraft('save');state.pendingOperation=op;show('save');return;}
    if(state.saveMode==='conflict'){state.conflictOperation=op;state.modalDrafts.save={'save-question':question,'save-check':nextCheck};state.modalDirty.save=true;show('conflict');return;}
    commitDemoQuestion(op);
